events=[]
mode='normal'
class S(str):
 def __hash__(self):
  events.append('hash')
  if mode=='hashraise': raise ValueError('hash')
  return str.__hash__(self)
 def __str__(self): raise ValueError('str')
 def __eq__(self, other):
  events.append(('eq', other))
  if mode=='raise': raise ValueError('equal')
  if mode=='false': return False
  if mode=='true': return True
  return str.__eq__(self, other)
if mode=='unhashable': S.__hash__=None
u=int|str
try:
 value=type(u).__getattribute__(u,S('__module__'))
 result=('ok',repr(value))
except Exception as e:
 result=(type(e).__name__,str(e),e.args)
result=(result,events)

